CREATE VIEW v61046 AS SELECT COALESCE(x1.HEX(FROM_BASE64('ABCD=')), x1.HEX(x1.v60986)), COALESCE(MAX(x1.HEX(FROM_BASE64('ABCD='))), 0), COALESCE(1, '1'), COALESCE(x1.HEX(POLYGON(LINESTRING(POINT(0, 0), POINT(1, 0), POINT(0, 0)))), x1.HEX(FROM_BASE64('ABCD='))), COALESCE(1, '1'), COALESCE(x1.HEX(FROM_BASE64('ABCD=')), x1.HEX(POLYGON(LINESTRING(POINT(0, 0), POINT(1, 0), POINT(0, 0))))) FROM v61037 AS x1